{
  "units": [
    {
      "quote_ref": "F000",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Section heading for Section 9908, entitled 'Application and plan'."
    },
    {
      "quote_ref": "F001",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Subsection heading for Section 9908(a), entitled 'Designation of lead agency'."
    },
    {
      "quote_ref": "F002",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Paragraph heading for Section 9908(a)(1), entitled 'Designation'."
    },
    {
      "quote_ref": "F003",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "The chief executive officer of a State desiring to receive a grant or allotment under section 9905 or 9906 of this title must designate, in an application submitted to the Secretary under subsection (b), an appropriate State agency that complies with the requirements of paragraph (2) to act as a lead agency for purposes of carrying out State activities under this chapter."
    },
    {
      "quote_ref": "F005",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "The lead agency designated under paragraph (1) shall carry out the specified duties under paragraph (2)."
    },
    {
      "quote_ref": "F006",
      "scope_refs": ["F005"],
      "kind": "requirement",
      "meaning": "The lead agency shall develop the State plan to be submitted to the Secretary under subsection (b)."
    },
    {
      "quote_ref": "F007",
      "scope_refs": ["F005"],
      "kind": "requirement",
      "meaning": "In conjunction with developing the State plan under subsection (b), the lead agency shall hold at least one hearing in the State with sufficient time and statewide distribution of notice, to provide the public an opportunity to comment on the proposed use and distribution of funds provided through the grant or allotment under section 9905 or 9906 for the period covered by the State plan."
    },
    {
      "quote_ref": "F008",
      "scope_refs": ["F005"],
      "kind": "requirement",
      "meaning": "The lead agency shall conduct reviews of eligible entities under section 9914 of this title."
    },
    {
      "quote_ref": "F010",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Paragraph heading for Section 9908(a)(3), entitled 'Legislative hearing'."
    },
    {
      "quote_ref": "F011",
      "scope_refs": [],
      "kind": "condition",
      "meaning": "In order to be eligible to receive a grant or allotment under section 9905 or 9906 of this title, the State must hold at least one legislative hearing every 3 years in conjunction with the development of the State plan."
    },
    {
      "quote_ref": "F013",
      "scope_refs": [],
      "kind": "condition",
      "meaning": "Beginning with fiscal year 2000, to be eligible to receive a grant or allotment under section 9905 or 9906 of this title, a State must prepare and submit to the Secretary an application and State plan covering not less than 1 fiscal year and not more than 2 fiscal years, submitted not later than 30 days prior to the beginning of the first fiscal year covered by the plan, containing such information as the Secretary requires."
    },
    {
      "quote_ref": "F014",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The application and State plan shall contain an assurance that funds made available through the grant or allotment will be used in accordance with subparagraphs (A), (B), and (C)."
    },
    {
      "quote_ref": "F015",
      "scope_refs": ["F013", "F014"],
      "kind": "requirement",
      "meaning": "Funds made available through the grant or allotment must be used to support activities designed to assist low-income families and individuals (including those receiving assistance under part A of title IV of the Social Security Act, homeless families and individuals, migrant or seasonal farmworkers, and elderly low-income individuals and families), and the plan must include a description of how such activities will enable the families and individuals to achieve specified goals."
    },
    {
      "quote_ref": "F016",
      "scope_refs": ["F013", "F014", "F015"],
      "kind": "requirement",
      "meaning": "The activities supported must enable low-income families and individuals to remove obstacles and solve problems that block the achievement of self-sufficiency, including self-sufficiency for those attempting to transition off a State program carried out under part A of title IV of the Social Security Act."
    },
    {
      "quote_ref": "F017",
      "scope_refs": ["F013", "F014", "F015"],
      "kind": "requirement",
      "meaning": "The activities supported must enable low-income families and individuals to secure and retain meaningful employment."
    },
    {
      "quote_ref": "F018",
      "scope_refs": ["F013", "F014", "F015"],
      "kind": "requirement",
      "meaning": "The activities supported must enable low-income families and individuals to attain an adequate education, with particular attention toward improving literacy skills of low-income families in the communities involved, which may include carrying out family literacy initiatives."
    },
    {
      "quote_ref": "F019",
      "scope_refs": ["F013", "F014", "F015"],
      "kind": "requirement",
      "meaning": "The activities supported must enable low-income families and individuals to make better use of available income."
    },
    {
      "quote_ref": "F020",
      "scope_refs": ["F013", "F014", "F015"],
      "kind": "requirement",
      "meaning": "The activities supported must enable low-income families and individuals to obtain and maintain adequate housing and a suitable living environment."
    },
    {
      "quote_ref": "F021",
      "scope_refs": ["F013", "F014", "F015"],
      "kind": "requirement",
      "meaning": "The activities supported must enable low-income families and individuals to obtain emergency assistance through loans, grants, or other means to meet immediate and urgent family and individual needs."
    },
    {
      "quote_ref": "F022",
      "scope_refs": ["F013", "F014", "F015"],
      "kind": "requirement",
      "meaning": "The activities supported must enable low-income families and individuals to achieve greater participation in community affairs, including developing public and private grassroots partnerships with local law enforcement agencies, local housing authorities, private foundations, and other partners."
    },
    {
      "quote_ref": "F023",
      "scope_refs": ["F013", "F014", "F015", "F022"],
      "kind": "requirement",
      "meaning": "Grassroots partnerships developed to achieve greater community participation must document best practices based on successful grassroots intervention in urban areas to develop methodologies for widespread replication."
    },
    {
      "quote_ref": "F024",
      "scope_refs": ["F013", "F014", "F015", "F022"],
      "kind": "requirement",
      "meaning": "Grassroots partnerships developed to achieve greater community participation must strengthen and improve relationships with local law enforcement agencies, which may include participation in neighborhood or community policing efforts."
    },
    {
      "quote_ref": "F026",
      "scope_refs": ["F013", "F014"],
      "kind": "requirement",
      "meaning": "Funds made available through the grant or allotment must be used to address youth needs in low-income communities through youth development programs that support the primary role of the family, prioritize youth problem and crime prevention, promote community coordination/collaboration, and support developing and expanding innovative community-based youth development programs with demonstrated success in preventing or reducing youth crime."
    },
    {
      "quote_ref": "F027",
      "scope_refs": ["F013", "F014", "F026"],
      "kind": "permission",
      "meaning": "Innovative community-based youth development programs may include programs establishing violence-free zones involving youth development and intervention models (such as youth mediation, youth mentoring, life skills training, job creation, and entrepreneurship programs)."
    },
    {
      "quote_ref": "F028",
      "scope_refs": ["F013", "F014", "F026"],
      "kind": "permission",
      "meaning": "Innovative community-based youth development programs may include after-school child care programs."
    },
    {
      "quote_ref": "F029",
      "scope_refs": ["F013", "F014"],
      "kind": "requirement",
      "meaning": "Funds made available through the grant or allotment must be used to make more effective use of, and coordinate with, other programs related to the chapter's purposes, including State welfare reform efforts."
    },
    {
      "quote_ref": "F031",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State plan must contain a description of how the State intends to use discretionary funds made available from the remainder of the grant or allotment described in section 9907(b) in accordance with this chapter, including how the State will support innovative community and neighborhood-based initiatives related to the chapter's purposes."
    },
    {
      "quote_ref": "F032",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State plan must include information provided by eligible entities in the State as specified in subparagraphs (A) through (D)."
    },
    {
      "quote_ref": "F033",
      "scope_refs": ["F013", "F032"],
      "kind": "requirement",
      "meaning": "The information provided by eligible entities must contain a description of the service delivery system for services provided or coordinated with funds made available through grants under section 9907(a), targeted to low-income individuals and families in communities within the State."
    },
    {
      "quote_ref": "F034",
      "scope_refs": ["F013", "F032"],
      "kind": "requirement",
      "meaning": "The information provided by eligible entities must contain a description of how linkages will be developed to fill identified service gaps through the provision of information, referrals, case management, and followup consultations."
    },
    {
      "quote_ref": "F035",
      "scope_refs": ["F013", "F032"],
      "kind": "requirement",
      "meaning": "The information provided by eligible entities must contain a description of how funds made available through grants under section 9907(a) will be coordinated with other public and private resources."
    },
    {
      "quote_ref": "F036",
      "scope_refs": ["F013", "F032"],
      "kind": "requirement",
      "meaning": "The information provided by eligible entities must contain a description of how the local entity will use funds to support innovative community and neighborhood-based initiatives related to the chapter's purposes, which may include fatherhood initiatives and other initiatives aimed at strengthening families and encouraging effective parenting."
    },
    {
      "quote_ref": "F038",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State plan must contain an assurance that eligible entities in the State will provide, on an emergency basis, supplies, services, nutritious foods, and related services necessary to counteract starvation and malnutrition conditions among low-income individuals."
    },
    {
      "quote_ref": "F039",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State plan must contain an assurance that the State and eligible entities will coordinate and establish linkages between governmental and other social services programs to assure effective delivery and avoid duplication, along with a description of how they will coordinate employment and training activities (as defined in section 3 of the Workforce Innovation and Opportunity Act) with entities providing activities through statewide and local workforce development systems under that Act."
    },
    {
      "quote_ref": "F040",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State plan must contain an assurance that the State will ensure coordination between antipoverty programs in each community, and ensure where appropriate that emergency energy crisis intervention programs under title XXVI (relating to low-income home energy assistance) are conducted in such community."
    },
    {
      "quote_ref": "F041",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State plan must contain an assurance that the State will permit and cooperate with Federal investigations undertaken in accordance with section 9916 of this title."
    },
    {
      "quote_ref": "F042",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State plan must contain an assurance that any eligible entity that received CSBG funding under this chapter in the previous fiscal year will not have its funding terminated or reduced below its previous proportional share unless, after notice and opportunity for a hearing on the record, the State determines cause exists, subject to review by the Secretary under section 9915(b)."
    },
    {
      "quote_ref": "F043",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State plan must contain an assurance that the State and eligible entities will, to the maximum extent possible, coordinate programs with and form partnerships with other organizations serving low-income residents and groups served by the State, including religious organizations, charitable groups, and community organizations."
    },
    {
      "quote_ref": "F044",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State plan must contain an assurance that the State will require each eligible entity in the State to establish procedures under which a low-income individual, community organization, religious organization, or representative of low-income individuals that considers itself or low-income individuals inadequately represented on the board (or other mechanism) of the entity may petition for adequate representation."
    },
    {
      "quote_ref": "F045",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State plan must contain an assurance that the State will secure from each eligible entity, as a condition to receipt of CSBG funding for a program, a community action plan (to be submitted to the Secretary upon request with the State plan) containing a community-needs assessment for the community served, which may be coordinated with assessments conducted for other programs."
    },
    {
      "quote_ref": "F046",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State plan must contain an assurance that the State and all eligible entities will, not later than fiscal year 2001, participate in the Results Oriented Management and Accountability System, another performance measure system facilitated by the Secretary pursuant to section 9917(b), or an alternative meeting that section's requirements, along with a description of outcome measures to measure eligible entity performance in promoting self-sufficiency, family stability, and community revitalization."
    },
    {
      "quote_ref": "F047",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State plan must include information describing how the State will carry out the assurances described in subsection (b)."
    },
    {
      "quote_ref": "F049",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Subsection heading and lead-in for Section 9908(c), establishing the definition of 'cause' for determinations under subsection (b)(8)."
    },
    {
      "quote_ref": "F050",
      "scope_refs": ["F049"],
      "kind": "definition",
      "meaning": "For purposes of making a determination in accordance with subsection (b)(8) with respect to a funding reduction, the term 'cause' includes the circumstances specified in subparagraphs (A) and (B)."
    },
    {
      "quote_ref": "F051",
      "scope_refs": ["F049", "F050"],
      "kind": "definition",
      "meaning": "For a funding reduction under subsection (b)(8), 'cause' includes a statewide redistribution of CSBG funds provided under this chapter to respond to specified criteria."
    },
    {
      "quote_ref": "F052",
      "scope_refs": ["F049", "F050", "F051"],
      "kind": "definition",
      "meaning": "A statewide redistribution constitutes 'cause' for a funding reduction when undertaken to respond to the results of the most recently available census or other appropriate data."
    },
    {
      "quote_ref": "F053",
      "scope_refs": ["F049", "F050", "F051"],
      "kind": "definition",
      "meaning": "A statewide redistribution constitutes 'cause' for a funding reduction when undertaken to respond to the designation of a new eligible entity."
    },
    {
      "quote_ref": "F054",
      "scope_refs": ["F049", "F050", "F051"],
      "kind": "definition",
      "meaning": "A statewide redistribution constitutes 'cause' for a funding reduction when undertaken to respond to severe economic dislocation."
    },
    {
      "quote_ref": "F055",
      "scope_refs": ["F049", "F050"],
      "kind": "definition",
      "meaning": "For a funding reduction under subsection (b)(8), 'cause' includes the failure of an eligible entity to comply with the terms of an agreement or a State plan, or to meet a State requirement, as described in section 9915(a) of this title."
    },
    {
      "quote_ref": "F057",
      "scope_refs": ["F049"],
      "kind": "definition",
      "meaning": "For purposes of a determination under subsection (b)(8) with respect to a termination, the term 'cause' includes the failure of an eligible entity to comply with the terms of an agreement or a State plan, or to meet a State requirement, as described in section 9915(a) of this title."
    },
    {
      "quote_ref": "F059",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Subsection heading for Section 9908(d), entitled 'Procedures and information'."
    },
    {
      "quote_ref": "F060",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "The Secretary may prescribe procedures for the purpose of assessing the effectiveness of eligible entities in carrying out the purposes of this chapter."
    },
    {
      "quote_ref": "F062",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Subsection heading for Section 9908(e), entitled 'Revisions and inspection'."
    },
    {
      "quote_ref": "F063",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Paragraph heading for Section 9908(e)(1), entitled 'Revisions'."
    },
    {
      "quote_ref": "F064",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "The chief executive officer of each State may revise any plan prepared under this section and must submit the revised plan to the Secretary."
    },
    {
      "quote_ref": "F066",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Paragraph heading for Section 9908(e)(2), entitled 'Public inspection'."
    },
    {
      "quote_ref": "F067",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Each plan or revised plan prepared under this section must be made available for public inspection within the State in such a manner as will facilitate review of, and comment on, the plan."
    },
    {
      "quote_ref": "F069",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Subsection heading for Section 9908(f), entitled 'Transition'."
    },
    {
      "quote_ref": "F070",
      "scope_refs": [],
      "kind": "condition",
      "meaning": "For fiscal year 2000, to be eligible to receive a grant or allotment under section 9905 or 9906 of this title, a State must prepare and submit to the Secretary an application and State plan in accordance with chapter provisions as in effect on the day before October 27, 1998, rather than subsections (a) through (c) relating to applications and plans."
    },
    {
      "quote_ref": "F071",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Statutory history note indicating enactment by Pub. L. 97–35, addition by Pub. L. 105–285, and amendment by Pub. L. 113–128."
    },
    {
      "quote_ref": "F072",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Editorial Notes header."
    },
    {
      "quote_ref": "F073",
      "scope_refs": [],
      "kind": "background",
      "meaning": "References in Text section header."
    },
    {
      "quote_ref": "F074",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Editorial note explaining the references to the Social Security Act in subsection (b)(1)(A)."
    },
    {
      "quote_ref": "F075",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Editorial note explaining the reference to the Workforce Innovation and Opportunity Act in subsection (b)(5)."
    },
    {
      "quote_ref": "F076",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Editorial note explaining the reference to Title XXVI in subsection (b)(6)."
    },
    {
      "quote_ref": "F077",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Prior Provisions header."
    },
    {
      "quote_ref": "F078",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Editorial note regarding prior section 9908 of Title 42."
    },
    {
      "quote_ref": "F079",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Editorial note regarding prior section 676 of Pub. L. 97–35."
    },
    {
      "quote_ref": "F080",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Amendments header."
    },
    {
      "quote_ref": "F081",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Editorial note detailing the 2014 amendment made by Pub. L. 113–128 to subsection (b)(5)."
    },
    {
      "quote_ref": "F082",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Statutory Notes and Related Subsidiaries header."
    },
    {
      "quote_ref": "F083",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Header for Effective Date of 2014 Amendment note."
    },
    {
      "quote_ref": "F084",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Note explaining that the amendment by Pub. L. 113–128 is effective on the first day of the first full program year after July 22, 2014 (July 1, 2015)."
    }
  ]
}
